// --- THREE TREFOILS FROM ONE SCRIPT ---
// On the Tubes sub-tab the script describes the AXIS of the tubes: it returns
// the point vec4(x, y, z, p) of the curve at u, and the tube is built around it.
// Each MESH_BEGIN section below is one tube, and `mesh` (0, 1, 2) tells them
// apart: the same trefoil, turned by 120 degrees around z and lifted a little
// for each tube. "thickness: 0.5" makes the second tube half as thick as the
// Thickness field; each tube can have its own color in the Renderer dock.
//MESH_BEGIN
u: 0, TAU, 200
v: 0, TAU, 32
//MESH_END
//MESH_BEGIN
u: 0, TAU, 200
v: 0, TAU, 32
thickness: 0.5
//MESH_END
//MESH_BEGIN
u: 0, TAU, 200
v: 0, TAU, 32
//MESH_END
float a = mesh * 2.0943951;
float x = (sin(u) + 2.0*sin(2.0*u)) / 3.0;
float y = (cos(u) - 2.0*cos(2.0*u)) / 3.0;
float z = -sin(3.0*u) / 3.0 + 0.4*(mesh - 1.0);
return vec4(x*cos(a) - y*sin(a), x*sin(a) + y*cos(a), z, 0.0);
